package kz.zeroops.api;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="managed_servers") public class ManagedServer {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="owner_id",nullable=false) private AppUser owner; @Column(nullable=false,length=100) private String name; @Column(nullable=false,length=255) private String host; @Column(nullable=false,length=64) private String environment; @Column(nullable=false,columnDefinition="TEXT") private String labels="{}"; @Enumerated(EnumType.STRING) @Column(nullable=false,length=16) private ServerStatus status=ServerStatus.PENDING; @Column(name="agent_token_hash",length=64) private String agentTokenHash; @Column(nullable=false) private Instant createdAt=Instant.now(); @Column(nullable=false) private Instant updatedAt=Instant.now(); @Column private Instant lastSeen;
 protected ManagedServer(){} public ManagedServer(AppUser owner,String name,String host,String environment,String labels){this.owner=owner;this.name=name;this.host=host;this.environment=environment;this.labels=labels;}
 public Long getId(){return id;} public AppUser getOwner(){return owner;} public String getName(){return name;} public String getHost(){return host;} public String getEnvironment(){return environment;} public String getLabels(){return labels;} public ServerStatus getStatus(){return status;} public String getAgentTokenHash(){return agentTokenHash;} public Instant getCreatedAt(){return createdAt;} public Instant getLastSeen(){return lastSeen;} public void update(String name,String host,String environment,String labels){this.name=name;this.host=host;this.environment=environment;this.labels=labels;this.updatedAt=Instant.now();} public void status(ServerStatus status){this.status=status;this.updatedAt=Instant.now();} public void setAgentTokenHash(String value){agentTokenHash=value;} public void seen(){lastSeen=Instant.now();status=ServerStatus.ONLINE;updatedAt=Instant.now();}
}
